solution.solution.js:
function makeCounter(start = 0, step = 1) {
  let current = start;
  return {
    next() { current += step; return current; },
    reset() { current = start; },
    value() { return current; },
  };
}

function memoize(f) {
  const seen = [];
  const results = [];
  return x => {
    const i = seen.indexOf(x);
    if (i !== -1) return results[i];
    const result = f(x);
    seen.push(x);
    results.push(result);
    return result;
  };
}

function makeLimiter(limit) {
  return f => {
    let calls = 0;
    return (...args) => {
      if (calls >= limit) return undefined;
      calls++;
      return f(...args);
    };
  };
}

unitTests:
test("counter keeps private state", () => {
  const a = makeCounter();
  const b = makeCounter(10, 5);
  checkEq([a.next(), a.next(), a.value()], [1, 2, 2]);
  checkEq([b.next(), b.next()], [15, 20]);
  b.reset();
  checkEq(b.value(), 10);
  checkEq(a.value(), 2);
});

test("memoize calls f once per argument", () => {
  let calls = 0;
  const slowSquare = x => { calls++; return x * x; };
  const fast = memoize(slowSquare);
  checkEq([fast(4), fast(4), fast(5), fast(4)], [16, 16, 25, 16]);
  checkEq(calls, 2);
  let zeroCalls = 0;
  const z = memoize(() => { zeroCalls++; return undefined; });
  z(1); z(1);
  checkEq(zeroCalls, 1);
});

test("limiter stops after the limit", () => {
  const twice = makeLimiter(2);
  const add = twice((a, b) => a + b);
  checkEq([add(1, 2), add(3, 4), add(5, 6)], [3, 7, undefined]);
  const other = twice(() => "x");
  checkEq([other(), other(), other()], ["x", "x", undefined]);
});

